sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float amount;
uniform float curve;
uniform float mode;
uniform float angle;
uniform float2 center;
uniform float baseSplit;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float2 d = coord - center * size;
    float2 dir = mode < 0.5 ? float2(cos(radians(angle)), sin(radians(angle))) : d / max(length(d), 0.001) * (length(d) / (length(size) * 0.5));
    float2 off = dir * (baseSplit + amount * e);
    float4 cr = tex(coord + off);
    float4 cg = tex(coord);
    float4 cb = tex(coord - off);
    return fin(c, float4(cr.r, cg.g, cb.b, cg.a), opacity);
}
